/*
 * ILI9341 TFT Display — draw colorful text and shapes.
 *
 * Wiring (Arduino Uno to ILI9341):
 *   5V   to VCC
 *   GND  to GND
 *   D10  to CS
 *   D9   to DC
 *   D11  to MOSI
 *   D13  to SCK
 */

#include <Adafruit_GFX.h>
#include <Adafruit_ILI9341.h>

#define TFT_CS  10
#define TFT_DC   9

Adafruit_ILI9341 tft(TFT_CS, TFT_DC);

int counter = 0;

void setup() {
  tft.begin();
  tft.setRotation(1);

  // Fill screen with navy
  tft.fillScreen(ILI9341_NAVY);

  // Title
  tft.setTextColor(ILI9341_YELLOW);
  tft.setTextSize(2);
  tft.setCursor(20, 20);
  tft.println("ArduSim TFT");

  // Subtitle
  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(1);
  tft.setCursor(20, 50);
  tft.println("ILI9341 240x320 Color Display");

  // Decorative border
  tft.drawRect(5, 5, 310, 230, ILI9341_CYAN);
  tft.drawRect(8, 8, 304, 224, ILI9341_DARKCYAN);

  // Draw color swatches
  uint16_t colors[] = {
    ILI9341_RED, ILI9341_GREEN, ILI9341_BLUE,
    ILI9341_YELLOW, ILI9341_CYAN, ILI9341_MAGENTA,
    ILI9341_ORANGE, ILI9341_WHITE
  };
  for (int i = 0; i < 8; i++) {
    tft.fillRect(20 + i * 35, 70, 30, 30, colors[i]);
  }

  // Circle demo
  tft.drawCircle(160, 160, 40, ILI9341_GREEN);
  tft.fillCircle(160, 160, 20, ILI9341_DARKGREEN);

  // Triangle
  tft.fillTriangle(80, 180, 60, 220, 100, 220, ILI9341_RED);
  tft.drawTriangle(200, 180, 220, 220, 180, 220, ILI9341_ORANGE);

  delay(2000);
}

void loop() {
  counter++;

  // Update counter text
  tft.fillRect(20, 110, 200, 20, ILI9341_NAVY);
  tft.setTextColor(ILI9341_WHITE);
  tft.setTextSize(1);
  tft.setCursor(20, 115);
  tft.print("Count: ");
  tft.print(counter);

  // Animated dot
  int x = 20 + (counter * 7) % 260;
  tft.fillCircle(x, 140, 5, ILI9341_CYAN);
  delay(300);
  tft.fillCircle(x, 140, 5, ILI9341_NAVY);
}
